  "remap.selected": {"en": "Selected button", "zh": "所选按键", "ja": "選択中のボタン", "ru": "Выбранная кнопка", "es": "Botón seleccionado", "fr": "Bouton sélectionné" },
  "remap.reset": {"en": "Restore original binding", "zh": "恢复原始映射", "ja": "元の割り当てに戻す", "ru": "Вернуть исходное назначение", "es": "Restaurar asignación original", "fr": "Rétablir l'affectation d'origine" },
  "remap.apply": {"en": "Changes are staged. Use Write to controller when you’re ready.", "zh": "更改已暂存。准备好后点击写入手柄。", "ja": "変更は編集中です。準備ができたら本体へ書き込んでください。", "ru": "Изменения подготовлены. Нажмите «Записать в контроллер», когда будете готовы.", "es": "Los cambios están preparados. Pulsa Escribir en el mando cuando estés listo.", "fr": "Les modifications sont préparées. Utilisez Écrire dans la manette quand vous êtes prêt." },
  "remap.readonly": {"en": "This action is read-only.", "zh": "此操作为只读。", "ja": "この操作は読み取り専用です。", "ru": "Это действие доступно только для чтения.", "es": "Esta acción es de solo lectura.", "fr": "Cette action est en lecture seule." },
