  "cal.web.title": {"en": "Hardware calibration", "zh": "硬件校准", "ja": "ハードウェア校正", "ru": "Аппаратная калибровка", "es": "Calibración de hardware", "fr": "Calibration matérielle" },
  "cal.web.flow": {"en": "Calibration procedure", "zh": "校准流程", "ja": "校正手順", "ru": "Порядок калибровки", "es": "Procedimiento de calibración", "fr": "Procédure de calibration" },
  "cal.web.parts": {"en": "Calibration parts", "zh": "校准部件", "ja": "校正する部品", "ru": "Компоненты калибровки", "es": "Partes a calibrar", "fr": "Éléments à calibrer" },
  "cal.web.both": {"en": "Sticks and triggers", "zh": "摇杆与扳机", "ja": "スティックとトリガー", "ru": "Стики и триггеры", "es": "Sticks y gatillos", "fr": "Sticks et gâchettes" },
  "cal.web.sticks": {"en": "Sticks only", "zh": "仅摇杆", "ja": "スティックのみ", "ru": "Только стики", "es": "Solo sticks", "fr": "Sticks uniquement" },
  "cal.web.triggers": {"en": "Triggers only", "zh": "仅扳机", "ja": "トリガーのみ", "ru": "Только триггеры", "es": "Solo gatillos", "fr": "Gâchettes uniquement" },
  "cal.web.motion": {"en": "Motion", "zh": "体感", "ja": "モーション", "ru": "Датчик движения", "es": "Movimiento", "fr": "Mouvement" },
  "cal.web.neutral": {"en": "Release the sticks and triggers to their neutral positions.", "zh": "松开摇杆和扳机，保持在中立位置。", "ja": "スティックとトリガーを離し、中立位置に戻します。", "ru": "Отпустите стики и триггеры в нейтральное положение.", "es": "Suelta los sticks y los gatillos en su posición neutra.", "fr": "Relâchez les sticks et les gâchettes en position neutre." },
  "cal.web.still": {"en": "Place the controller flat on a stable surface and keep it still.", "zh": "将手柄平放在稳定桌面，保持静止。", "ja": "安定した机に平らに置き、動かさないでください。", "ru": "Положите геймпад на устойчивую поверхность и не двигайте его.", "es": "Coloca el mando plano sobre una superficie estable y no lo muevas.", "fr": "Posez la manette à plat sur une surface stable et ne la bougez pas." },
  "cal.web.move": {"en": "Click Start calibration. Slowly rotate the sticks through a full circle; fully press and release the triggers.", "zh": "点击开始校准。缓慢转动摇杆覆盖完整圆周；完全按下并松开扳机。", "ja": "校正開始を押し、スティックをゆっくり一周させ、トリガーを最後まで押して離します。", "ru": "Нажмите «Начать калибровку». Медленно вращайте стики по полному кругу; полностью нажмите и отпустите триггеры.", "es": "Haz clic en Iniciar calibración. Gira despacio los sticks en un círculo completo; pulsa y suelta los gatillos a fondo.", "fr": "Cliquez sur Démarrer la calibration. Faites lentement un cercle complet avec les sticks ; enfoncez et relâchez complètement les gâchettes." },
  "cal.web.startStill": {"en": "Click Start calibration and continue to keep the controller still.", "zh": "点击开始校准。继续保持静止。", "ja": "校正開始を押し、そのまま動かさずに待ちます。", "ru": "Нажмите «Начать калибровку» и не двигайте геймпад.", "es": "Haz clic en Iniciar calibración y sigue sin mover el mando.", "fr": "Cliquez sur Démarrer la calibration et continuez à garder la manette immobile." },
  "cal.web.observe": {"en": "Watch the device status, then click Complete calibration when finished. To cancel, click Exit calibration.", "zh": "观察设备状态，完成后点击完成校准；需要取消时点击退出。", "ja": "状態を確認して校正完了を押します。中止する場合は校正を終了を押します。", "ru": "Следите за состоянием устройства. Затем нажмите «Завершить калибровку»; для отмены нажмите «Выйти из калибровки».", "es": "Observa el estado del dispositivo y haz clic en Completar calibración al terminar. Para cancelar, haz clic en Salir de la calibración.", "fr": "Surveillez l'état de l'appareil, puis cliquez sur Terminer la calibration. Pour annuler, cliquez sur Quitter la calibration." },
  "cal.web.start": {"en": "Start calibration", "zh": "开始校准", "ja": "校正開始", "ru": "Начать калибровку", "es": "Iniciar calibración", "fr": "Démarrer la calibration" },
  "cal.web.finish": {"en": "Complete calibration", "zh": "完成校准", "ja": "校正完了", "ru": "Завершить калибровку", "es": "Completar calibración", "fr": "Terminer la calibration" },
  "cal.web.exit": {"en": "Exit calibration", "zh": "退出校准", "ja": "校正を終了", "ru": "Выйти из калибровки", "es": "Salir de la calibración", "fr": "Quitter la calibration" },
  "cal.web.notStarted": {"en": "Not started", "zh": "未开始", "ja": "未開始", "ru": "Не начато", "es": "Sin iniciar", "fr": "Non démarrée" },
  "cal.web.running": {"en": "Calibrating", "zh": "校准中", "ja": "校正中", "ru": "Калибровка", "es": "Calibrando", "fr": "Calibration en cours" },
  "cal.web.waiting": {"en": "Waiting for device", "zh": "等待设备", "ja": "デバイス待機中", "ru": "Ожидание устройства", "es": "Esperando al dispositivo", "fr": "En attente de l'appareil" },
  "cal.web.status": {"en": "Calibration status", "zh": "校准状态", "ja": "校正状態", "ru": "Состояние калибровки", "es": "Estado de la calibración", "fr": "État de la calibration" },
  "cal.web.left": {"en": "Left stick", "zh": "左摇杆", "ja": "左スティック", "ru": "Левый стик", "es": "Stick izquierdo", "fr": "Stick gauche" },
