  'unsaved.hideDetail': { en: 'They stay staged while Stick Labs runs in the tray, but they are not on the controller until you press Write.', zh: 'Stick Labs 在托盘运行时更改会保留，但在点击写入前不会应用到手柄。', ja: 'トレイで動作中は変更が保持されますが、書き込むまでコントローラーには反映されません。', ru: 'Изменения сохранятся, пока Stick Labs работает в трее, но попадут в контроллер только после записи.', "es": "Se mantienen preparados mientras Stick Labs sigue en la bandeja, pero no están en el mando hasta que pulses Escribir.", "fr": "Elles restent préparées tant que Stick Labs tourne dans la barre des tâches, mais ne sont pas dans la manette tant que vous n'appuyez pas sur Écrire." },
  'unsaved.quitDetail': { en: 'Quitting discards them. They were never written to the controller.', zh: '退出将放弃这些更改，它们尚未写入手柄。', ja: '終了すると変更は破棄されます。コントローラーには書き込まれていません。', ru: 'При выходе изменения будут потеряны: они не были записаны в контроллер.', "es": "Al salir se descartan. Nunca se escribieron en el mando.", "fr": "Quitter les abandonne. Elles n'ont jamais été écrites dans la manette." },
  'unsaved.hide': { en: 'Hide to tray', zh: '隐藏到托盘', ja: 'トレイに隠す', ru: 'Свернуть в трей', "es": "Ocultar en la bandeja", "fr": "Réduire dans la barre" },
  'unsaved.quit': { en: 'Quit anyway', zh: '仍然退出', ja: '終了する', ru: 'Всё равно выйти', "es": "Salir de todos modos", "fr": "Quitter quand même" },
  'unsaved.keep': { en: 'Keep editing', zh: '继续编辑', ja: '編集を続ける', ru: 'Продолжить', "es": "Seguir editando", "fr": "Continuer à modifier" },
  'review.title': { en: 'Review changes — P{slot}', zh: '检查更改 — P{slot}', ja: '変更を確認 — P{slot}', ru: 'Проверка изменений — P{slot}', "es": "Revisar cambios — P{slot}", "fr": "Vérifier les modifications — P{slot}" },
  'review.none': { en: 'No byte changes against the controller. Writing will re-save the same profile.', zh: '与手柄相比没有字节更改。写入将重新保存相同的配置。', ja: 'コントローラーとの差分はありません。同じプロファイルを再保存します。', ru: 'Отличий от контроллера нет. Запись сохранит тот же профиль.', "es": "No hay cambios de bytes respecto al mando. Escribir volverá a guardar el mismo perfil.", "fr": "Aucun octet ne diffère de la manette. Écrire réenregistrera le même profil." },
  'review.full': { en: 'Full profile (no previous read to compare against)', zh: '完整配置（无可对比的读取记录）', ja: 'プロファイル全体（比較できる読み込みなし）', ru: 'Весь профиль (нет прочитанных данных для сравнения)', "es": "Perfil completo (no hay lectura previa con la que comparar)", "fr": "Profil complet (aucune lecture précédente pour comparer)" },
