  'cal.stepS1': { en: 'Sample 1 of 2', zh: '采样 1/2', ja: 'サンプル 1/2', ru: 'Замер 1 из 2', "es": "Muestra 1 de 2", "fr": "Mesure 1 sur 2" },
  'cal.stepS2': { en: 'Sample 2 of 2', zh: '采样 2/2', ja: 'サンプル 2/2', ru: 'Замер 2 из 2', "es": "Muestra 2 de 2", "fr": "Mesure 2 sur 2" },
  'cal.tipRest': { en: 'Leave the pad untouched on a table while open. Values are steps off centre (128); ±2 is perfect.', zh: '开启时请勿触碰手柄。数值为相对中心(128)的步数，±2 为完美。', ja: '調整中は触れないでください。128中心のステップ数、±2が理想。', ru: 'Не трогайте геймпад на столе, пока сессия открыта. Значения — шаги от центра (128); ±2 — идеально.', "es": "Deja el mando sin tocar sobre una mesa mientras esté abierto. Los valores son pasos respecto al centro (128); ±2 es perfecto.", "fr": "Laissez la manette posée sur une table sans y toucher pendant la session. Les valeurs sont des pas par rapport au centre (128) ; ±2 est parfait." },
  'cal.driftWarn': { en: 'This bench re-centers the sticks — it cannot fix drift. Drift is worn hardware; replace the sticks, then calibrate.', zh: '此校准台只能回中——无法修复漂移。漂移是硬件磨损；请更换摇杆后再校准。', ja: 'このベンチはセンター調整のみ — ドリフトは直せません。摩耗です。交換してから調整してください。', ru: 'Этот стенд возвращает стики в центр — дрейф он не лечит. Дрейф — износ железа; замените стики, затем калибруйте.', "es": "Este banco recentra los sticks; no puede arreglar el drift. El drift es desgaste del hardware: cambia los sticks y luego calibra.", "fr": "Ce banc recentre les sticks — il ne peut pas corriger la dérive. La dérive vient d'une usure matérielle : remplacez les sticks, puis calibrez." },
