  'profiles.title': { en: 'Stick profiles', zh: '摇杆配置', ja: 'スティックプロファイル', ru: 'Профили стиков', "es": "Perfiles de sticks", "fr": "Profils de sticks" },
  'buttons.title': { en: 'Button remap', zh: '按键映射', ja: 'ボタンリマップ', ru: 'Переназначение кнопок', "es": "Reasignar botones", "fr": "Réaffectation des boutons" },
  'buttons.hint': { en: 'One press in, one press out — single controller or keyboard targets only, the same bytes Connect writes. Turbo and toggle bytes are never touched. Multi-maps written in Connect show their first target here.', zh: '一按进一按出——仅单个目标（手柄按键或键盘），与 Connect 写入的字节一致。从不动 turbo 与切换字节。在 Connect 里写的多重映射这里只显示第一个目标。', ja: '1入力1出力 — 単一ターゲットのみ（パッドボタンまたはキーボード）、Connectと同じバイトを書き込みます。ターボ/トグルには触れません。Connectの複数マップは最初のターゲットのみ表示。', ru: 'Одно нажатие — один выход: только одиночные цели (контроллер или клавиатура), те же байты, что пишет Connect. Байты turbo и toggle не трогаем. Мультимаппинги из Connect показывают здесь первую цель.', "es": "Una pulsación entra, una sale: solo destinos únicos de mando o teclado, los mismos bytes que escribe Connect. Los bytes de turbo y alternancia nunca se tocan. Las asignaciones múltiples hechas en Connect muestran aquí su primer destino.", "fr": "Une pression en entrée, une en sortie — uniquement des cibles uniques manette ou clavier, les mêmes octets que Connect écrit. Les octets turbo et bascule ne sont jamais modifiés. Les affectations multiples faites dans Connect affichent ici leur première cible." },
  'buttons.help': { en: 'Button mapping help', zh: '按键映射说明', ja: 'ボタン割り当てのヘルプ', ru: 'Справка по назначению кнопок', "es": "Ayuda de asignación de botones", "fr": "Aide sur l'affectation des boutons" },
  'buttons.source': { en: 'Button', zh: '按键', ja: 'ボタン', ru: 'Кнопка', "es": "Botón", "fr": "Bouton" },
