  'topbar.sub': { en: 'bit depth + raw unlock · curves · live sticks', zh: '位深 + 原生解锁 · 曲线 · 实时摇杆', ja: 'ビット深度 + RAW解放 · カーブ · ライブ', ru: 'разрядность + raw-разблок · кривые · живые стики', "es": "profundidad de bits + desbloqueo raw · curvas · sticks en directo", "fr": "profondeur de bits + déblocage brut · courbes · sticks en direct" },
  'msg.receiver': { en: 'That PID is the receiver, not the pad — reads time out on it. Disconnect and connect the ★ interface instead.', zh: '该 PID 是接收器而非手柄——读取会超时。请断开并连接 ★ 接口。', ja: 'そのPIDはレシーバーです — 読み取りはタイムアウトします。★接口に接続し直してください。', ru: 'Этот PID — приёмник, а не геймпад: чтение зависнет. Отключитесь и подключите интерфейс ★.', "es": "Ese PID es el receptor, no el mando: las lecturas agotan el tiempo. Desconecta y conecta la interfaz ★.", "fr": "Ce PID est le récepteur, pas la manette — les lectures expirent. Déconnectez-vous et connectez plutôt l'interface ★." },
  'msg.fw': { en: 'FW', zh: '固件', ja: 'FW', ru: 'Прошивка', "es": "FW", "fr": "FW" },
