  'community.offline': { en: "Couldn't load community curves. Check your connection and press Refresh.", zh: "无法载入社区曲线。请检查网络后点击刷新。", ja: "コミュニティカーブを読み込めませんでした。接続を確認して更新を押してください。", ru: "Не удалось загрузить кривые сообщества. Проверьте подключение и нажмите «Обновить».", es: "No se pudieron cargar las curvas de la comunidad. Revisa tu conexión y pulsa Actualizar.", fr: "Impossible de charger les courbes de la communauté. Vérifiez votre connexion et appuyez sur Actualiser." },
  'community.loading': { en: "Loading community curves…", zh: "正在载入社区曲线…", ja: "コミュニティカーブを読み込み中…", ru: "Загрузка кривых сообщества…", es: "Cargando curvas de la comunidad…", fr: "Chargement des courbes de la communauté…" },
  'community.noMatch': { en: "No curves match.", zh: "没有匹配的曲线。", ja: "一致するカーブはありません。", ru: "Ничего не найдено.", es: "Ninguna curva coincide.", fr: "Aucune courbe ne correspond." },
  'community.empty': { en: "No community curves yet. Be the first: press \"Submit my curve\".", zh: "还没有社区曲线。点击“提交我的曲线”成为第一个！", ja: "まだコミュニティカーブはありません。「自分のカーブを投稿」で最初の一人に！", ru: "Кривых сообщества пока нет. Станьте первым — нажмите «Опубликовать мою кривую».", es: "Aún no hay curvas de la comunidad. Sé el primero: pulsa «Publicar mi curva».", fr: "Aucune courbe pour l’instant. Soyez le premier : appuyez sur « Publier ma courbe »." },
